      "q": "【題組（四）】\n火車進站了，震耳的磨鐵聲混合著長長一聲「汽——」。我抓著父親的手，母親兩手提著大捆的行李，三兄的臉上瞧不出別親的思緒，他早已說清楚，他恨極了車水抓泥，也不喜歡土角茨，不喜歡牛糞餅，不喜歡剝得下一層指甲厚的乾土的布衣，不喜歡母親說的話。母親說：「小漢仔才九歲，幫阿爹還得靠你。」三兄踏進火車的肚子，父親眼睜睜的像是瞧著水圳的水一直流入別人的田裡，而自己腳踏的土地仍然乾裂成龜背上的紋理。（阿盛〈火車與稻田〉）\n\n9. 這段文字表現出農村的何種情況？",
